function saveActiveTask(){const t=taskById(activeTaskId);if(!t)return;const title=$('#task-title').value.trim();if(!title){$('#task-title').value=t.title;showToast('El título no puede quedar vacío');return}t.title=title;t.description=$('#task-description').value.trim();t.status=$('#task-status').value;t.assignee=$('#task-assignee').value;t.priority=$('#task-priority').value;t.updated=nowIso();normalizeOrders();persist();$('#save-state').textContent='Guardado';render()}
function queueSave(){const t=taskById(activeTaskId);if(!t)return;$('#save-state').textContent='Guardando…';clearTimeout(saveTimer);saveTimer=setTimeout(saveActiveTask,250)}
function autoSize(el){if(!el)return;el.style.height='auto';el.style.height=Math.min(el.scrollHeight,220)+'px'}
function renderTaskTags(t){const b=currentBoard();$('#task-tags').innerHTML=b.tags.length?b.tags.map(tag=>`<button type="button" class="tag-toggle ${t.tags.includes(tag)?'active':''}" data-task-tag="${esc(tag)}">${esc(tag)}</button>`).join(''):`<small class="tiny-meta">Aún no hay tags en este tablero.</small>`}
function renderSubtasks(t){const done=t.subtasks.filter(s=>s.done).length;$('#subtask-progress').textContent=t.subtasks.length?`${done}/${t.subtasks.length}`:'';$('#subtasks').innerHTML=t.subtasks.map(s=>`<div class="subtask ${s.done?'done':''}"><label><input type="checkbox" data-subtask-check="${esc(s.id)}" ${s.done?'checked':''}><span>${esc(s.text)}</span></label><button type="button" data-subtask-delete="${esc(s.id)}" aria-label="Eliminar subtarea">×</button></div>`).join('')}
function renderComments(t){$('#comment-count').textContent=t.comments.length?String(t.comments.length):'';$('#comments').innerHTML=t.comments.map(c=>{const p=person(c.author)||{name:'Persona'};return`<article class="comment"><div class="comment-head"><span>${esc(p.name)}</span><button type="button" data-comment-delete="${esc(c.id)}">Eliminar</button></div><p>${esc(c.text)}</p></article>`}).join('')}
function toggleTaskTag(tag){const t=taskById(activeTaskId),b=currentBoard();if(!t||!b.tags.includes(tag))return;if(t.tags.includes(tag))t.tags=t.tags.filter(x=>x!==tag);else t.tags.push(tag);t.updated=nowIso();persist();renderTaskTags(t);render()}
function addSubtask(text){const t=taskById(activeTaskId);text=text.trim();if(!t||!text)return;if(t.subtasks.length>=MAX_SUBTASKS)return showToast(`Máximo ${MAX_SUBTASKS} subtareas`);t.subtasks.push({id:uid('st'),text,done:false});t.updated=nowIso();persist();renderSubtasks(t);render();$('#subtask-input').value=''}
function addComment(text){const t=taskById(activeTaskId);text=text.trim();if(!t||!text)return;if(t.comments.length>=MAX_COMMENTS)return showToast(`Máximo ${MAX_COMMENTS} comentarios`);t.comments.push({id:uid('cm'),author:ME,text,created:nowIso()});t.updated=nowIso();persist();renderComments(t);render();$('#comment-input').value=''}
function createBoard(){const title=prompt('Nombre del tablero','Nuevo tablero');if(!title?.trim())return;const id=uid('board');const columns=DEFAULT_COLUMNS.map((title,i)=>({id:`${id}-c${i+1}`,title}));const b={id,title:title.trim().slice(0,48),columns,tags:['UX','UI','Bug','QA'],tasks:[]};commit('Crear tablero',()=>{state.boards.push(b);state.activeBoardId=id;state.activeColumnId=columns[0].id},'Tablero creado');closeDialog('board-picker-dialog')}
function duplicateBoard(){const src=currentBoard(),id=uid('board');const colMap=new Map(src.columns.map((c,i)=>[c.id,`${id}-c${i+1}`]));const b={id,title:`${src.title} copia`.slice(0,48),columns:src.columns.map((c,i)=>({id:`${id}-c${i+1}`,title:c.title})),tags:[...src.tags],tasks:src.tasks.map((t,i)=>({...clone(t),id:`${id}-t${i+1}`,status:colMap.get(t.status),subtasks:t.subtasks.map(s=>({...s,id:uid('st')})),comments:t.comments.map(c=>({...c,id:uid('cm')}))}))};commit('Duplicar tablero',()=>{state.boards.push(b);state.activeBoardId=id;state.activeColumnId=b.columns[0].id},'Tablero duplicado');closeDialog('settings-dialog')}
function deleteBoard(){if(state.boards.length<=1)return showToast('Debe quedar al menos un tablero');const b=currentBoard();if(!confirm(`¿Eliminar “${b.title}”?`))return;commit('Eliminar tablero',()=>{state.boards=state.boards.filter(x=>x.id!==b.id);state.activeBoardId=state.boards[0].id;state.activeColumnId=state.boards[0].columns[0].id},'Tablero eliminado');closeDialog('settings-dialog')}
